using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class CalendarPage:UserControl{MonthCalendar cal;DataGridView grid;public CalendarPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;var left=Ui.Card();left.Dock=DockStyle.Left;left.Width=280;cal=new MonthCalendar{MaxSelectionCount=1};cal.DateChanged+=(s,e)=>LoadDay();left.Controls.Add(cal);Controls.Add(left);grid=Ui.Grid();Controls.Add(grid);grid.BringToFront();LoadDay();}void LoadDay(){grid.DataSource=Database.Query("SELECT i.Id,c.FullName Candidate,j.Title Job,i.ScheduledAt,i.InterviewType,i.Interviewer,i.Status FROM Interviews i JOIN Applications a ON a.Id=i.ApplicationId JOIN Candidates c ON c.Id=a.CandidateId JOIN Jobs j ON j.Id=a.JobId WHERE CAST(i.ScheduledAt AS DATE)=@d ORDER BY i.ScheduledAt",new System.Data.SqlClient.SqlParameter("@d",cal.SelectionStart.Date));}}}
